CODE_SLOT_SCHEMA = _code_slot_schema(password=False)


# What a form offers before any lock answers: the setup flow, which has no
# lock set up yet, and an entry that is not loaded (spec decision 4).
_PIN_ONLY: frozenset[CredentialType] = frozenset({CredentialType.PIN})


def _offered_types(entry: ConfigEntry | None) -> frozenset[CredentialType]:
    """
    Return the credential types the entry's locks take.

    Known only once the entry is loaded: its locks are what answer. ``None``
    is the setup flow, whose entry does not exist yet.
    """
    if entry is None or getattr(entry, "runtime_data", None) is None:
        return _PIN_ONLY
    return available_credential_types(entry)


def _offers_password(entry: ConfigEntry) -> bool:
    """Return whether the entry's locks take passwords."""
    return CredentialType.PASSWORD in _offered_types(entry)


def _slot_enabled_without_credential(
    slot: Mapping[str, Any], offered: Collection[CredentialType]
) -> bool:
    """Return True if a slot is enabled but holds no credential of an offered type."""
    return bool(slot.get(CONF_ENABLED)) and not has_credential(slot, offered)

....
    ``taken`` is whichever users the block is being added alongside, empty
    when it IS the whole configuration. A block added to an entry has to
    clear the users already there as well as its own: two keys meaning one
    person collapse into a single key on the way into storage whether they
    arrived together or a week apart, and a credential two users share is
    recorded as either of them whoever presents it.

    Returns the parsed users -- or ``None`` when validation failed -- with the
    accumulated errors and description placeholders.
    """
    # A block still keyed by slot number coerces cleanly into users named
    # "1", "2", which is a silently wrong reading of what was pasted.
    if raw_users and all(isinstance(key, int) for key in raw_users):
        return None, {"base": "users_keyed_by_slot"}, {}

    try:
        parsed_users = USERS_SCHEMA(raw_users)
    except vol.Invalid as err:
        _LOGGER.error("Invalid users: %s", err)
        return None, {"base": "invalid_config"}, {}

    offered = _offered_types(config_entry)
    if (
        bare := next(
            (
                name
                for name, fields in parsed_users.items()
                if _slot_enabled_without_credential(fields, offered)
            ),
            None,
        )
    ) is not None:
        _LOGGER.error(
            "Invalid users: %s is enabled without a credential a lock takes", bare
        )
        return None, {"base": "invalid_config"}, {}

    if problem := validate_user_names(parsed_users):
        name, error = problem
        return None, {"base": error}, {"name": name}

    spoken_for = {identity(name) for name in taken}
    for name in parsed_users:
        if identity(name) in spoken_for:
            return None, {"base": "name_not_unique"}, {"name": name}

    seen: dict[str, Mapping[str, Any]] = dict(taken)
    for name, fields in parsed_users.items():
        if duplicates := _duplicate_credentials(fields, seen):
            # Its own message: a block has no field to mark, so it names whose.
            credential = next(iter(duplicates))
            return None, {"base": f"{credential}_not_unique_in_block"}, {"name": name}
        seen[name] = fields

    # The same refusal the guided path gives. Both write the one field, so a
    # condition entity this integration cannot read must fail on both routes
    # or the editor becomes a way around the check.
    ent_reg = er.async_get(hass)
    for name, fields in parsed_users.items():
        if not (condition := fields.get(CONF_CONDITION)):
            continue
        entity_entry = ent_reg.async_get(condition)
        if entity_entry and entity_entry.platform in EXCLUDED_CONDITION_PLATFORMS:
            return (
                None,
                {"base": "excluded_platform"},
                {
                    "name": name,
                    "integration": entity_entry.platform,
                    "docs_url": (
                        "https://github.com/raman325/lock_code_manager/wiki/"
                        "Unsupported-Condition-Entity-Integrations"
                    ),
                },
            )

    # The count is what a lock has to hold, now that nobody picks a number --
    # everyone the entry will hold once this block lands, not just the block.
    wanted = len(taken) + len(parsed_users)
    try:
        await async_check_slot_capacity(hass, config_entry, locks, [wanted])
....
    Turn a user off, and clear their credential from the entry's locks.

    Unconditional, unlike enabling: there is no state a user can be in that
    makes turning them off invalid. Their credential stays in the
    configuration, so enabling them again restores it without anybody
    having to remember what it was.
    """
    coordinator = _slot_coordinator_for(hass, name, config_entry_id, config_entry_title)
    await coordinator.async_request_active_toggle(False)


async def async_add_users(
    hass: HomeAssistant,
    users: list[dict[str, Any]],
    *,
    config_entry_id: str | None = None,
    config_entry_title: str | None = None,
) -> None:
    """
    Add one or more users to an entry, numbering them by reading the locks.

    All or nothing. Every name is validated, one allocation covers the whole
    batch, and one write lands it. Partial success would leave the caller
    working out which of a list arrived, and nothing here needs it: every way
    this can fail -- a name that means somebody already here, a batch that
    will not fit -- is knowable before anything is written.

    Adding N users one call at a time would read the locks N times, which on a
    battery lock is the difference between usable and not, and would settle
    the entry N times over.
    """
    config_entry = get_loaded_config_entry(hass, config_entry_id, config_entry_title)
    config = get_entry_config(config_entry)
    offered = available_credential_types(config_entry)

    additions: dict[str, dict[str, Any]] = {}
    for entry in users:
        name = entry[CONF_NAME]
        if error := name_error(name):
            raise ServiceValidationError(f"Invalid name {name!r}: {error}")
        name = normalize_name(name)
        # Checked against the batch as well as the entry: two names in one
        # call meaning one person would collapse into a single key on the way
        # into storage, taking one of their credentials with it.
        if any(
            identity(known) == identity(name) for known in (*config.users, *additions)
        ):
            raise ServiceValidationError(f"A user named {name!r} already exists")

        credentials = credential_values(entry)
        enabled = entry.get(CONF_ENABLED, True)
        condition = entry.get(CONF_CONDITION)

        # The same rule the editor enforces: a slot cannot be programmed
        # without something a lock in the entry is given (spec decision 4).
        if enabled and not has_credential(entry, offered):
            raise ServiceValidationError(
                f"{name!r} cannot be enabled without a PIN or password"
            )
        for credential_type, value in credentials.items():
            if error := credential_value_error(credential_type, value):
                raise ServiceValidationError(f"{name!r}: {error}")
            if (
                holder := credential_holder(
                    {**config.users, **additions}, credential_type, value
                )
            ) is not None:
                noun = credential_noun(credential_type.value)
                raise ServiceValidationError(
                    f"{name!r} cannot have the {noun} {holder!r} already has"
                )
        if condition:
            _async_validate_condition(hass, condition)

        user: dict[str, Any] = {
            CONF_ENABLED: enabled,
            **{
                credential_type.value: value
                for credential_type, value in credentials.items()
            },
        }

